void buildStateMatrix_2(vector<int> m, int B[5][5][64]){
	for(int i = 0; i < 1600; i++)
	B[(i/64)%5][i/320][i%64]=m[i];
}
   
const int r_ro[5][5] = {
    { 0, 36, 3, 41, 18},
    { 1, 44,10, 45,  2},
    {62,  6,43, 15, 61},
    {28, 55,25, 21, 56},
    {27, 20,39,  8, 14}
};

int B_1[5][5][64];

void ro(int in[5][5][64], int out[5][5][64]){
    for(int i = 0; i < 5; i++){
        for(int j = 0; j < 5; j++){
            for(int k = 0; k < 64; k++){
                if(in[i][j][k]){
                    out[i][j][(k-r_ro[i][j]+64)%64]=1;
                }
            }
        }
    }
}

int B_2[5][5][64];

void pi(int in[5][5][64], int out[5][5][64]){
    for(int i = 0; i < 5; i++){
        for(int j = 0; j < 5; j++){
            for(int k = 0; k < 64; k++){
                if(in[i][j][k]){
                    out[(1*i+3*j)%5][i][k]=1;
                }
            }
        }
    }
}

int B_3[1600];

void To1600(int in[5][5][64], int out[1600]){
    for(int i = 0; i < 5; i++){
        for(int j = 0; j < 5; j++){
            for(int k = 0; k < 64; k++){
                out[64*(5*j+i)+k] = in[i][j][k];
            }
        }
    }
}
   
// 將原檔案一的 main 封裝成函式，回傳長度 1600 的 vector
vector<int> getVectorFromFile1() {
    buildStateMatrix_2(beta_1, B);
    pi(B, B_2);
    ro(B_2, B_1);
    To1600(B_1, B_3);
    
    vector<int> resultVector(1600);
    for (int i = 0; i < 1600; i++) {
        resultVector[i] = B_3[i]; 
    }
    return resultVector;
}


