typedef vector<vector<int>> Matrix2D; // 原名 Matrix，改名避免衝突

Matrix2D mat_A(1600, vector<int>(1600, 0)); // 原名 A，改名避免衝突
Matrix2D C(1600, vector<int>(3200, 0));
Matrix2D C1(1600, vector<int>(1600, 0));

