void Construct(Matrix2D& m) {
    // 1. 初始化矩陣為全 0
    for (int i = 0; i < 1600; i++) {
        for (int j = 0; j < 1600; j++) {
            m[i][j] = 0;
        }
    }

    // 2. 這裡的 i_out 代表「輸出」的 index (也就是矩陣的第 i_out 個 Row)
    for (int i_out = 0; i_out < 1600; i_out++) {
        // 解析這個輸出的三維座標
        int y_out = i_out / 320;
        int x_out = (i_out / 64) % 5;
        int z_out = i_out % 64;

        // --- 完全照著公式順序寫 ---
        
        // 項目 1: A[x, y, z] (自己原本位置的輸入)
        // 輸入的 index 剛好跟輸出一樣
        m[i_out][i_out] ^= 1; 

        // 項目 2: C[x-1, z] (左邊那列 5 個 y 的總和)
        int left_x = (x_out + 4) % 5; // 即 x-1
        for (int y_in = 0; y_in < 5; y_in++) {
            int in_idx_left = 320 * y_in + 64 * left_x + z_out;
            m[i_out][in_idx_left] ^= 1; // 把矩陣該 Column 填上 1
        }

        // 項目 3: C[x+1, z-1] (右邊那列 5 個 y 的總和，注意 z 要減 1)
        int right_x = (x_out + 1) % 5; // 即 x+1
        int prev_z = (z_out + 63) % 64; // 即 z-1
        for (int y_in = 0; y_in < 5; y_in++) {
            int in_idx_right = 320 * y_in + 64 * right_x + prev_z;
            m[i_out][in_idx_right] ^= 1; // 把矩陣該 Column 填上 1
        }
    }
}

// 建構增廣矩陣 [A | I]
void Construct2(Matrix2D& m){
    for(int i = 0; i < 1600; i++) {
        for(int j = 0; j < 1600; j++) {
            m[i][j] = mat_A[i][j];
        }
        m[i][i + 1600] = 1;
    }
}

// 在 GF(2) 進行高斯-喬登消去法
void Gaussian(Matrix2D& D){
    for(int i = 0; i < 1600; i++) {
        int pivot = i;
        while (pivot < 1600 && D[pivot][i] == 0) {
            pivot++;
        }
        if (pivot == 1600) {
            cerr << "Warning: Matrix is not invertible at column " << i << "!" << endl;
            return;
        }
        if (pivot != i) {
            swap(D[i], D[pivot]);
        }
        for(int r = 0; r < 1600; r++) {
            if(r != i && D[r][i] == 1) {
                for(int c = i; c < 3200; c++) {
                    D[r][c] ^= D[i][c];
                }
            }
        }
    }
}

// 取出增廣矩陣的右半部，即為反矩陣
void Construct3(Matrix2D& m){
    for(int i = 0; i < 1600; i++) {
        for(int j = 0; j < 1600; j++) {
            C1[i][j] = m[i][j + 1600];
        }
    }
}

// 將原檔案二的 main 封裝成函式，回傳 1600x1600 矩陣
Matrix2D getInverseThetaMatrix() {
    Construct(mat_A);
    Construct2(C);
    Gaussian(C);
    Construct3(C);
    return C1;
}

// ==========================================
// 合併與計算邏輯：GF(2) 的矩陣乘上向量
// ==========================================
vector<int> multiplyMatrixVectorGF2(const Matrix2D& matrix, const vector<int>& vec) {
    int rows = matrix.size();
    int cols = matrix[0].size();
    vector<int> result(rows, 0);

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            // 在 GF(2) 中，乘法等同於 AND (&)，加法等同於 XOR (^)
            result[i] ^= (matrix[i][j] & vec[j]);
        }
    }
    return result;
}

int main() {
    // 1. 從第一個檔案邏輯取得 1600 維向量
    vector<int> myVector = getVectorFromFile1();
    
    // 2. 從第二個檔案邏輯取得 1600x1600 的反矩陣
    Matrix2D myMatrix = getInverseThetaMatrix();

    // 3. 進行矩陣與向量的乘法運算
    vector<int> finalResult = multiplyMatrixVectorGF2(myMatrix, myVector);

    // 4. 印出結果 (連續印出1600個位元)
    cout << "相乘後的結果向量 (1600 bits):" << endl;
    for (int i = 0; i < 1600; i++) {
        cout << finalResult[i]<<",";
    }
    cout << endl;

    return 0;
}
